    50	export async function mirrorCourseOnPear(course: Course): Promise<CourseNetworkInfo> {
    51		if (!enabled()) return offline();
    52		try {
    53			let entryPromise = feeds.get(course.id);
    54			if (!entryPromise) {
    55				entryPromise = openFeed(course);
    56				feeds.set(course.id, entryPromise);
    57			}
    58			const entry = await entryPromise;
    59			if (entry.lastRevision < course.revision) {
    60				await entry.feed.setSnapshot(projectCourseForPear(course));
    61				entry.lastRevision = course.revision;
    62			}
