    66				status: "connected",
    67				peerCount: stats.peers,
    68				publicKey: entry.feed.publicKey,
    69			};
    70		} catch (error) {
    71			feeds.delete(course.id);
    72			console.warn("Keating course Pear gateway is unavailable:", error instanceof Error ? error.message : "unknown error");
