     1	import { useCallback, useEffect, useState } from "react";
     2	import { isNotOrganicFeatureEnabled } from "../notorganic-provider";
     3	
     4	export interface CoursesAccount {
     5		id: string;
     6		displayName: string;
     7	}
     8	
     9	export type CoursesAccessState =
    10		| { status: "loading" }
    11		| { status: "disabled" }
    12		| { status: "signed-out"; error: string }
    13		| { status: "ready"; account: CoursesAccount };
    14	
    15	export function useCoursesAccess(): [CoursesAccessState, () => void] {
    16		const [nonce, setNonce] = useState(0);
    17		const [state, setState] = useState<CoursesAccessState>({ status: "loading" });
    18		useEffect(() => {
    19			let cancelled = false;
    20			if (!isNotOrganicFeatureEnabled()) {
    21				setState({ status: "disabled" });
    22				return;
    23			}
    24			setState({ status: "loading" });
    25			fetch("/api/courses/session")
    26				.then(async (response) => {
    27					const body = await response.json().catch(() => ({}));
    28					if (!response.ok) throw new Error(body?.statusMessage ?? body?.message ?? "Your Not Organic session is unavailable.");
    29					return body.account as CoursesAccount;
    30				})
    31				.then((account) => {
    32					if (!cancelled) setState({ status: "ready", account });
    33				})
    34				.catch((error) => {
    35					if (!cancelled) setState({
    36						status: "signed-out",
    37						error: error instanceof Error ? error.message : "Your Not Organic session is unavailable.",
    38					});
    39				});
    40			return () => {
    41				cancelled = true;
    42			};
    43		}, [nonce]);
    44		return [state, useCallback(() => setNonce((value) => value + 1), [])];
    45	}

