 83	export function permissionsFor(course: Course, accountId: string): CoursePermissions {
 84		const member = memberFor(course, accountId);
 85		const canTeach = roleCanTeach(member.role);
 86		return {
 87			canEditCourse: canTeach,
 88			canInvite: canTeach,
 89			canReview: canTeach,
 90			canEditDeck: canTeach || course.settings.allowPeerDeckEdits,
 91			canRequestTeacherAccess: canTeach,
 92		};
 93	}
 94	
 95	export function applyCourseOperation(
 96		current: Course,
 97		actorAccountId: string,
 98		operation: CourseOperation,
 99		now = new Date().toISOString(),
100	): Course {
101		if (operation.courseId !== current.id) {
102			throw new CourseNotFoundError("The operation targets a different course.");
103		}
104		if (operationNeedsCurrentRevision(operation) && operation.baseRevision !== current.revision) {
105			throw new CourseConflictError(
106				"The course changed while you were editing. Refresh and try again.",
107				current.revision,
108			);
109		}
110	
111		const actor = memberFor(current, actorAccountId);
112		const next = structuredClone(current);
113	
114		switch (operation.type) {
115			case "course.update": {
116				if (!roleCanTeach(actor.role)) {
117					throw new CourseAuthorizationError("Only course teachers can change course details.");
118				}
119				Object.assign(next, operation.patch);
120				break;
121			}
122			case "lesson.update": {
123				if (!roleCanTeach(actor.role)) {
124					throw new CourseAuthorizationError("Only course teachers can edit lessons.");
125				}
126				const module = next.modules.find((candidate) => candidate.id === operation.moduleId);
127				if (!module) throw new CourseNotFoundError("This module is no longer part of the course.");
128				const index = module.lessons.findIndex((lesson) => lesson.id === operation.lesson.id);
129				if (index === -1) module.lessons.push(operation.lesson);
130				else module.lessons[index] = operation.lesson;
131				break;
132			}
133			case "lesson.complete": {
134				assertLesson(next, operation.lessonId);
135				const target = next.members.find((member) => member.accountId === actorAccountId)!;
136				const completed = new Set(target.progress.completedLessonIds);
137				if (operation.completed) completed.add(operation.lessonId);
138				else completed.delete(operation.lessonId);
139				target.progress.completedLessonIds = [...completed];
140				target.progress.activeLessonId = operation.lessonId;
141				target.progress.lastActiveAt = now;
142				appendActivity(
143					next,
144					activity(
145						operation.id,
146						"lesson-completed",
147						actorAccountId,
148						operation.completed ? "Completed a lesson" : "Reopened a lesson",
149						now,
150						operation.lessonId,
151					),
152				);
153				break;
154			}
155			case "shared-note.update": {
156				assertLesson(next, operation.lessonId);
157				const index = next.sharedNotes.findIndex((note) => note.id === operation.noteId);
158				const existing = index === -1 ? null : next.sharedNotes[index];
159				if (existing && existing.version !== operation.baseVersion) {
160					throw new CourseConflictError(
161						"Someone else changed these shared notes. Review their version before saving yours.",
162						next.revision,
163					);
164				}
165				const note = {
166					id: operation.noteId,
167					lessonId: operation.lessonId,
168					title: operation.title,
169					text: operation.text,
170					version: (existing?.version ?? 0) + 1,
171					updatedAt: now,
172					updatedBy: actorAccountId,
173				};
174				if (index === -1) next.sharedNotes.push(note);
175				else next.sharedNotes[index] = note;
176				appendActivity(
177					next,
178					activity(operation.id, "note-updated", actorAccountId, "Updated shared notes", now, operation.lessonId),
179				);
180				break;
181			}
182			case "submission.save": {
183				assertLesson(next, operation.lessonId);
184				const index = next.submissions.findIndex(
185					(submission) =>
186						submission.id === operation.submissionId && submission.accountId === actorAccountId,
187				);
188				const existing = index === -1 ? null : next.submissions[index];
189				const submission: CourseSubmission = {
190					id: operation.submissionId,
191					lessonId: operation.lessonId,
192					exerciseId: operation.exerciseId,
193					accountId: actorAccountId,
194					answer: operation.answer,
195					sharedWithPeers: operation.sharedWithPeers,
196					version: (existing?.version ?? 0) + 1,
197					updatedAt: now,
198					...(existing?.review ? { review: existing.review } : {}),
199				};
200				if (index === -1) next.submissions.push(submission);
201				else next.submissions[index] = submission;
202				appendActivity(
203					next,
204					activity(operation.id, "submission-saved", actorAccountId, "Saved exercise work", now, operation.lessonId),
205				);
206				break;
207			}
208			case "submission.review": {
209				if (!roleCanTeach(actor.role)) {
210					throw new CourseAuthorizationError("Only course teachers can review submissions.");
211				}
212				const submission = next.submissions.find((candidate) => candidate.id === operation.submissionId);
213				if (!submission) throw new CourseNotFoundError("This submission could not be found.");
214				const student = memberFor(next, submission.accountId);
215				if (student.teacherAccess !== "full") {
216					throw new CourseAuthorizationError("The learner has not granted full teacher access.");
217				}
218				submission.review = {
219					status: operation.status,
220					feedback: operation.feedback,

221					reviewerAccountId: actorAccountId,
222					updatedAt: now,
223				};
224				appendActivity(
225					next,
226					activity(operation.id, "submission-reviewed", actorAccountId, "Reviewed exercise work", now, submission.lessonId),
227				);
228				break;
229			}
230			case "comment.add": {
231				if (!next.settings.allowPeerComments && !roleCanTeach(actor.role)) {
232					throw new CourseAuthorizationError("Peer comments are disabled for this course.");
233				}
234				assertLesson(next, operation.lessonId);
235				next.comments.push({
236					id: operation.commentId,
237					lessonId: operation.lessonId,
238					accountId: actorAccountId,
239					body: operation.body,
240					createdAt: now,
241				});
242				appendActivity(
243					next,
244					activity(operation.id, "comment-added", actorAccountId, "Added a lesson comment", now, operation.lessonId),
245				);
246				break;
247			}
248			case "card.upsert": {
249				if (!roleCanTeach(actor.role) && !next.settings.allowPeerDeckEdits) {
250					throw new CourseAuthorizationError("Only course teachers can edit this deck.");
251				}
252				const index = next.cards.findIndex((card) => card.id === operation.card.id);
253				const card = { ...operation.card, updatedAt: now, updatedBy: actorAccountId };
254				if (index === -1) next.cards.push(card);
255				else next.cards[index] = card;
256				appendActivity(
257					next,
258					activity(operation.id, "card-updated", actorAccountId, "Updated an Anki card", now, card.lessonId),
259				);
260				break;
261			}
262			case "material.add": {
263				if (!roleCanTeach(actor.role)) {
264					throw new CourseAuthorizationError("Only course teachers can add course materials.");
265				}
266				const material = { ...operation.material, createdAt: now, createdBy: actorAccountId };
267				const index = next.materials.findIndex((candidate) => candidate.id === material.id);
268				if (index === -1) next.materials.push(material);
269				else next.materials[index] = material;
270				appendActivity(next, activity(operation.id, "material-added", actorAccountId, "Added course material", now));
271				break;
272			}
273			case "teacher-access.request": {
274				if (!roleCanTeach(actor.role)) {
275					throw new CourseAuthorizationError("Only course teachers can request full access.");
276				}
277				const target = memberFor(next, operation.memberAccountId);
278				if (roleCanTeach(target.role)) {
279					throw new CourseAuthorizationError("Teacher access applies to learners and invited peers.");
280				}
281				target.teacherAccess = "requested";
282				appendActivity(
283					next,
284					activity(operation.id, "teacher-access-requested", actorAccountId, "Requested full teacher access", now),
285				);
286				break;
287			}
288			case "teacher-access.respond": {
289				const target = memberFor(next, actorAccountId);
290				if (target.teacherAccess !== "requested") {
291					throw new CourseConflictError("There is no active teacher-access request.", next.revision);
292				}
293				target.teacherAccess = operation.approve ? "full" : "private";
294				appendActivity(
295					next,
296					activity(
297						operation.id,
298						"teacher-access-changed",
299						actorAccountId,
300						operation.approve ? "Granted full teacher access" : "Declined full teacher access",
301						now,
302					),
303				);
304				break;
305			}
306			case "member.role.update": {
307				if (!roleCanOwn(actor.role)) {
308					throw new CourseAuthorizationError("Only the course owner can change member roles.");
309				}
310				const target = memberFor(next, operation.memberAccountId);
311				if (target.role === "owner") {
312					throw new CourseAuthorizationError("Transfer ownership before changing the owner role.");
313				}
314				target.role = operation.role;
315				appendActivity(
316					next,
317					activity(operation.id, "member-role-changed", actorAccountId, "Changed a course member role", now),
318				);
319				break;
320			}
321		}
322	
323		next.revision += 1;
324		next.updatedAt = now;
325		return next;
326	}
327	
328	function canSeeSubmission(course: Course, viewer: CourseMember, submission: CourseSubmission): boolean {
329		if (submission.accountId === viewer.accountId) return true;
330		if (roleCanTeach(viewer.role)) {
331			return memberFor(course, submission.accountId).teacherAccess === "full";
332		}
333		return submission.sharedWithPeers;
334	}
335	
336	export function projectCourseForViewer(course: Course, viewerAccountId: string): CourseViewerSnapshot {
337		const viewer = memberFor(course, viewerAccountId);
338		const projected = structuredClone(course);
339		projected.submissions = projected.submissions.filter((submission) =>
340			canSeeSubmission(course, viewer, submission),
341		);
342		return {
343			course: projected,
344			viewer: structuredClone(viewer),
345			permissions: permissionsFor(course, viewerAccountId),
346		};
347	}

