     1	import { useStorage } from "nitro/storage";
     2	import { z } from "zod";
     3	import {
     4		allCourseLessons,
     5		courseCreateInputSchema,
     6		courseInviteSchema,
     7		courseSchema,
     8		type Course,
     9		type CourseCreateInput,
    10		type CourseInvite,
    11		type CourseListItem,
    12		type CourseOperation,
    13		type CourseRole,
    14		type CourseViewerSnapshot,
    15	} from "../../src/courses/contracts";
    16	import {
    17		applyCourseOperation,
    18		permissionsFor,
    19		projectCourseForViewer,
    20	} from "../../src/courses/operations";
    21	
    22	const COURSE_STORAGE = "keating:courses";
    23	const MAX_APPLIED_OPERATIONS = 20_000;
    24	
    25	const storedCourseRecordSchema = z.object({
    26		course: courseSchema,
    27		appliedOperationIds: z.array(z.string()).max(MAX_APPLIED_OPERATIONS).default([]),
    28	});
    29	
    30	interface StoredCourseRecord {
    31		course: Course;
    32		appliedOperationIds: string[];
    33	}
    34	
    35	interface CourseRepositoryGlobals {
    36		__keatingCourseLocks?: Map<string, Promise<void>>;
    37	}
    38	
    39	const globals = globalThis as typeof globalThis & CourseRepositoryGlobals;
    40	const courseLocks = globals.__keatingCourseLocks ??= new Map<string, Promise<void>>();
    41	
    42	function randomId(prefix: string): string {
    43		return `${prefix}_${crypto.randomUUID().replaceAll("-", "")}`;
    44	}
    45	
    46	function randomToken(): string {
    47		const bytes = new Uint8Array(32);
    48		crypto.getRandomValues(bytes);
    49		return Buffer.from(bytes).toString("base64url");
    50	}
    51	
    52	async function sha256(value: string): Promise<string> {
    53		const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
    54		return Buffer.from(digest).toString("hex");
    55	}
    56	
    57	function storage() {
    58		return useStorage(COURSE_STORAGE);
    59	}
    60	
    61	function courseKey(courseId: string): string {
    62		return `course:${courseId}`;
    63	}
    64	
    65	async function accountKey(accountId: string): Promise<string> {
    66		return `account:${await sha256(accountId)}`;
    67	}
    68	
    69	async function withCourseLock<T>(courseId: string, task: () => Promise<T>): Promise<T> {
    70		const previous = courseLocks.get(courseId) ?? Promise.resolve();
    71		let release!: () => void;
    72		const gate = new Promise<void>((resolve) => {
    73			release = resolve;
    74		});
    75		const tail = previous.then(() => gate);
    76		courseLocks.set(courseId, tail);
    77		await previous;
    78		try {
    79			return await task();
    80		} finally {
    81			release();
    82			if (courseLocks.get(courseId) === tail) courseLocks.delete(courseId);
    83		}
    84	}
    85	
    86	async function loadRecord(courseId: string): Promise<StoredCourseRecord | null> {
    87		const raw = await storage().getItem(courseKey(courseId));
    88		if (!raw) return null;
    89		return storedCourseRecordSchema.parse(raw);
    90	}
    91	
    92	async function saveRecord(record: StoredCourseRecord): Promise<void> {
    93		await storage().setItem(courseKey(record.course.id), record);
    94	}
    95	
    96	async function addCourseToAccount(accountId: string, courseId: string): Promise<void> {
