   421			const char = text[index];
   422			if (char === '"') {
   423				if (quoted && text[index + 1] === '"') { field += '"'; index += 1; }
   424				else quoted = !quoted;
   425			} else if (char === delimiter && !quoted) {
   426				row.push(field); field = "";
   427			} else if ((char === "\n" || char === "\r") && !quoted) {
   428				if (char === "\r" && text[index + 1] === "\n") index += 1;
   429				row.push(field); field = "";
   430				if (row.some((cell) => cell.trim())) rows.push(row);
   431				row = [];
   432			} else field += char;
