   120	async function getJson<T>(url: string, fetcher: typeof fetch): Promise<T> {
   121		let response: Response;
   122		try {
   123			response = await fetcher(url, {
   124				headers: { accept: "application/json" },
   125				signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
   126			});
   127		} catch {
   128			throw new AtprotoBlogError("The AT Protocol blog source could not be reached", "upstream_unavailable");
   129		}
   130		if (!response.ok) {
   131			throw new AtprotoBlogError(
   132				response.status === 404
   133					? "The configured AT Protocol record was not found"
   134					: "The AT Protocol blog source returned an error",
   135				response.status === 404 ? "not_found" : "upstream_unavailable",
   136			);
   137		}
   138		try {
   139			return await response.json() as T;
   140		} catch {
   141			throw new AtprotoBlogError("The AT Protocol blog source returned invalid JSON", "invalid_data");
   142		}
   143	}
