   145	async function resolveRepoDid(config: AtprotoBlogConfig, fetcher: typeof fetch): Promise<string> {
   146		if (config.repo.startsWith("did:")) return config.repo;
   147		const url = new URL("/xrpc/com.atproto.identity.resolveHandle", config.handleResolver);
   148		url.searchParams.set("handle", config.repo);
   149		const payload = await getJson<{ did?: string }>(url.toString(), fetcher);
   150		if (typeof payload.did !== "string" || !payload.did.startsWith("did:")) {
   151			throw new AtprotoBlogError("The configured blog handle did not resolve to a DID", "invalid_data");
   152		}
   153		return payload.did;
   154	}
