   156	function didWebDocumentUrl(did: string): string {
   157		const segments = did.slice("did:web:".length).split(":").map((segment) => decodeURIComponent(segment));
   158		const hostname = segments.shift();
   159		if (!hostname || segments.some((segment) => !segment || segment === "." || segment === "..")) {
   160			throw new AtprotoBlogError("The configured did:web identifier is invalid", "invalid_data");
   161		}
   162		const path = segments.length > 0
   163			? `/${segments.map(encodeURIComponent).join("/")}/did.json`
   164			: "/.well-known/did.json";
   165		return `https://${hostname}${path}`;
   166	}
