   208	async function listRecords(
   209		pds: string,
   210		did: string,
   211		collection: string,
   212		fetcher: typeof fetch,
   213	): Promise<AtprotoRecordEnvelope[]> {
   214		const records: AtprotoRecordEnvelope[] = [];
   215		let cursor: string | undefined;
   216		do {
   217			const url = new URL("/xrpc/com.atproto.repo.listRecords", pds);
   218			url.searchParams.set("repo", did);
   219			url.searchParams.set("collection", collection);
   220			url.searchParams.set("limit", "100");
   221			url.searchParams.set("reverse", "true");
   222			if (cursor) url.searchParams.set("cursor", cursor);
   223			const payload = await getJson<ListRecordsResponse>(url.toString(), fetcher);
   224			if (!Array.isArray(payload.records)) {
   225				throw new AtprotoBlogError("The PDS returned an invalid record list", "invalid_data");
   226			}
   227			records.push(...payload.records);
   228			cursor = configuredString(payload.cursor);
   229		} while (cursor && records.length < MAX_RECORDS);
