   144	async function xrpcJson<T>(url: string, init: RequestInit): Promise<T> {
   145		const response = await fetch(url, init);
   146		const payload = await response.json().catch(() => null) as T & { error?: string; message?: string } | null;
   147		if (!response.ok || !payload) {
   148			const reason = payload?.message || payload?.error || response.statusText;
   149			throw new Error(`PDS request failed (${response.status}): ${reason}`);
   150		}
   151		return payload;
   152	}
