   154	async function createSession(pds: string, identifier: string, password: string): Promise<Required<Pick<SessionResponse, "did" | "accessJwt">>> {
   155		const session = await xrpcJson<SessionResponse>(`${pds}/xrpc/com.atproto.server.createSession`, {
   156			method: "POST",
   157			headers: { "content-type": "application/json" },
   158			body: JSON.stringify({ identifier, password }),
   159		});
   160		if (!session.did || !session.accessJwt) throw new Error("The PDS session response omitted its DID or access token");
   161		return { did: session.did, accessJwt: session.accessJwt };
   162	}
