   164	async function putRecord(pds: string, did: string, accessJwt: string, item: PublishRecord): Promise<void> {
   165		await xrpcJson(`${pds}/xrpc/com.atproto.repo.putRecord`, {
   166			method: "POST",
   167			headers: { authorization: `Bearer ${accessJwt}`, "content-type": "application/json" },
   168			body: JSON.stringify({
   169				repo: did,
   170				collection: item.collection,
   171				rkey: item.rkey,
   172				record: item.record,
   173				validate: false,
   174			}),
   175		});
   176	}
