   182	async function main(): Promise<void> {
   183		const shouldWrite = process.argv.includes("--write");
   184		const only = argumentValue("--only");
   185		const output = resolve(argumentValue("--output") ?? DEFAULT_OUTPUT);
   186		let did = process.env.KEATING_BLOG_DID?.trim() || "did:plc:replace-me";
   187		let accessJwt: string | undefined;
   188		let pds: string | undefined;
   189	
   190		if (shouldWrite) {
   191			pds = process.env.KEATING_BLOG_PDS_URL?.trim().replace(/\/$/, "");
   192			const identifier = process.env.KEATING_BLOG_IDENTIFIER?.trim();
   193			const password = process.env.KEATING_BLOG_APP_PASSWORD;
   194			if (!pds || !identifier || !password) {
   195				throw new Error("--write requires KEATING_BLOG_PDS_URL, KEATING_BLOG_IDENTIFIER, and KEATING_BLOG_APP_PASSWORD");
   196			}
   197			const session = await createSession(pds, identifier, password);
   198			did = session.did;
   199			accessJwt = session.accessJwt;
   200		}
