   202		const allRecords = buildLegacyStandardSiteRecords(did);
   203		const records = only
   204			? allRecords.filter((item) => item.collection === STANDARD_SITE_PUBLICATION_COLLECTION || item.rkey === only)
   205			: allRecords;
   206		if (only && records.length === 1) throw new Error(`No legacy post matched --only=${only}`);
   207	
   208		await mkdir(dirname(output), { recursive: true });
   209		await writeFile(output, `${JSON.stringify({ did, records }, null, 2)}\n`, "utf8");
   210	
   211		if (shouldWrite && pds && accessJwt) {
   212			for (const item of records) await putRecord(pds, did, accessJwt, item);
   213			console.log(`Published ${records.length} records to ${pds} for ${did}.`);
   214		} else {
   215			console.log(`Dry run: prepared ${records.length} records for ${did}.`);
   216		}
   217		console.log(`Record payloads: ${output}`);
   218		console.log(`Publication URI: at://${did}/${STANDARD_SITE_PUBLICATION_COLLECTION}/self`);
   219	}
